-- Additive, idempotent schema for Vertical Drama special tie-in episodes.
ALTER TABLE "vertical_drama_episodes" ADD COLUMN IF NOT EXISTS "episodeKind" varchar(24) NOT NULL DEFAULT 'normal', ADD COLUMN IF NOT EXISTS "specialSequence" integer, ADD COLUMN IF NOT EXISTS "specialData" jsonb;
UPDATE "vertical_drama_episodes" SET "episodeKind" = 'normal' WHERE "episodeKind" IS NULL;
CREATE TABLE IF NOT EXISTS "vertical_drama_special_sequence_counters" ("id" bigserial PRIMARY KEY NOT NULL, "tenantId" varchar(36) NOT NULL, "userId" integer NOT NULL REFERENCES "users"("id") ON DELETE cascade, "seriesId" bigint NOT NULL REFERENCES "vertical_drama_series"("id") ON DELETE cascade, "nextSequence" integer NOT NULL DEFAULT 1, "createdAt" timestamptz NOT NULL DEFAULT now(), "updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "vds_special_sequence_counter_series_unique" ON "vertical_drama_special_sequence_counters" ("tenantId", "seriesId");
CREATE INDEX IF NOT EXISTS "vds_special_sequence_counter_lookup_idx" ON "vertical_drama_special_sequence_counters" ("tenantId", "userId", "seriesId");
CREATE UNIQUE INDEX IF NOT EXISTS "vds_episode_special_sequence_unique" ON "vertical_drama_episodes" ("tenantId", "seriesId", "specialSequence") WHERE "episodeKind" = 'special_tie_in';
INSERT INTO "vertical_drama_special_sequence_counters" ("tenantId", "userId", "seriesId", "nextSequence") SELECT e."tenantId", min(e."userId"), e."seriesId", greatest(coalesce(max(e."specialSequence"), 0) + 1, 1) FROM "vertical_drama_episodes" e WHERE e."episodeKind" = 'special_tie_in' GROUP BY e."tenantId", e."seriesId" ON CONFLICT ("tenantId", "seriesId") DO UPDATE SET "nextSequence" = greatest("vertical_drama_special_sequence_counters"."nextSequence", EXCLUDED."nextSequence");
